"""Filter bad samples."""
def filter_fn(x: Any) -> object {
    if (x["label"] == -1) {
        return False;
    }
    if ("premise" in x) {
        if ((x["premise"] is None) or (x["premise"] == "")) {
            return False;
        }
    }
    if ("hypothesis" in x) {
        if ((x["hypothesis"] is None) or (x["hypothesis"] == "")) {
            return False;
        }
    }
    return True;
}

